package dev.industrialtechnology.spacecheck;
import java.util.*;import java.io.File;import java.lang.reflect.*;import java.nio.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.settings.KeyBinding;import net.minecraft.client.gui.inventory.GuiContainer;import net.minecraft.entity.*;import net.minecraft.entity.player.*;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.nbt.*;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.util.*;import net.minecraftforge.fluids.*;import org.lwjgl.opengl.GL11;import org.lwjgl.BufferUtils;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.space.*;import dev.industrialtechnology.client.space.*;
public final class SpaceClientChecks {
    private final List<String> results=Collections.synchronizedList(new ArrayList<String>());private volatile boolean failed,fixtureReady,landedSignal;private boolean finished;private int phase,wait=30,timeout,age,dimensionSeen;private EntityLivingBase camera;private double jumpStart,jumpMax;private int jumpPlanet;private static final boolean SHUTTLE=Boolean.getBoolean("industrialtech.shuttleClient");private static TileSpaceMachine pad,base;private static EntitySpaceRocket rocket;private static int leg;private static float savedHealth;private static int savedAir;private static double landX,landY,landZ;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String s){SpaceChecks.check(b,s);}
    private void pass(String s){results.add("PASS: "+s);}
    private void server(String label,Runnable action){ServerWork.enqueue(()->{try{action.run();pass(label);}catch(Throwable e){failed=true;results.add("FAIL: "+label+" :: "+e);IndustrialTechnology.log.error(label,e);}});}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private static WorldServer world(){return (WorldServer)player().worldObj;}
    private static EntitySpaceRocket find(){for(Object o:world().loadedEntityList)if(o instanceof EntitySpaceRocket&&!((Entity)o).isDead&&((EntitySpaceRocket)o).owner.equals(player().getUniqueID().toString()))return (EntitySpaceRocket)o;throw new AssertionError("Owned rocket missing");}
    private static void inventory(){EntityPlayerMP p=player();ItemStack s=p.inventory.getStackInSlot(0);check(s!=null&&s.getItem()==Items.diamond&&s.stackSize==23&&s.hasTagCompound()&&s.getTagCompound().getString("Sentinel").equals("space-trip"),"inventory changed");check(p.experienceLevel==37&&p.experienceTotal==5000,"XP changed");}
    private static void move(double x,double y,double z){EntityPlayerMP p=player();p.playerNetServerHandler.setPlayerLocation(x,y,z,0,0);p.fallDistance=0;}
    private void shot(String name){Minecraft mc=Minecraft.getMinecraft();ScreenShotHelper.saveScreenshot(mc.mcDataDir,name+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    private void click(int id)throws Exception {Minecraft mc=Minecraft.getMinecraft();check(mc.currentScreen instanceof GuiSpace,"Space GUI unavailable for button "+id);GuiSpace g=(GuiSpace)mc.currentScreen;Field f=GuiScreen.class.getDeclaredField("buttonList");f.setAccessible(true);for(Object o:(List)f.get(g)){GuiButton b=(GuiButton)o;if(b.id==id){Method m=GuiSpace.class.getDeclaredMethod("actionPerformed",GuiButton.class);m.setAccessible(true);m.invoke(g,b);return;}}throw new AssertionError("Button "+id+" absent");}
    private void openRocket(){server("Owned landed vehicle opens its actual server container",()->{rocket=find();move(rocket.posX+3,rocket.posY,rocket.posZ);player().openGui(IndustrialTechnology.instance,3,world(),rocket.getEntityId(),0,0);});}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END||finished)return;Minecraft mc=Minecraft.getMinecraft();if(failed){finish();return;}if(--wait>0)return;try{
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=2;mc.gameSettings.renderDistanceChunks=SHUTTLE?12:3;if(SHUTTLE){mc.gameSettings.clouds=false;mc.gameSettings.fovSetting=85;}mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(7741,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("space-client","Space Expansion Test",s);phase=1;wait=60;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++timeout>180)throw new AssertionError("Client join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);server("Craftable launch fixture, researched HDD and finite propellant initialize",()->{EntityPlayerMP p=player();WorldServer w=world();pad=SHUTTLE?ShuttleClientFixture.create(w,p):SpaceChecks.launchpad(w,32,70,32);pad.owner=p.getUniqueID().toString();pad.items[0]=SpaceChecks.rocket();pad.items[0].getTagCompound().setBoolean("Shuttle",SHUTTLE);pad.items[1]=new ItemStack(SpaceRegistry.hdd);NBTTagCompound n=new NBTTagCompound();n.setInteger("MoonTicks",SpaceConfig.moonResearch);n.setInteger("MarsTicks",SpaceConfig.marsResearch);pad.items[1].setTagCompound(n);pad.tanks[0].fill(new FluidStack(SpaceRegistry.kerosene,SpaceConfig.moonFuel*2),true);pad.tanks[1].fill(new FluidStack(SpaceRegistry.lox,SpaceConfig.moonFuel*2*SpaceConfig.oxygenRatio),true);pad.tanks[2].fill(new FluidStack(SpaceRegistry.air,1000),true);for(int i=0;i<4;i++){p.inventory.armorInventory[3-i]=new ItemStack(SpaceRegistry.suits[2][i]);ItemSpaceSuit.setAir(p.inventory.armorInventory[3-i],108000);}p.inventory.mainInventory[0]=new ItemStack(Items.diamond,23);NBTTagCompound sentinel=new NBTTagCompound();sentinel.setString("Sentinel","space-trip");p.inventory.mainInventory[0].setTagCompound(sentinel);p.experienceLevel=37;p.experienceTotal=5000;p.experience=.4f;p.setGameType(WorldSettings.GameType.SURVIVAL);move(pad.xCoord+.5,pad.yCoord+1,pad.zCoord+3.5);w.markBlockForUpdate(pad.xCoord,pad.yCoord,pad.zCoord);fixtureReady=true;});phase=15;wait=60;return;}
        if(phase==15&&SHUTTLE){if(!fixtureReady){if(++timeout>90)throw new AssertionError("Fixture timeout");wait=20;return;}phase=20;wait=80;return;}if(phase==15){server("Client has loaded the launchpad before opening its GUI",()->player().openGui(IndustrialTechnology.instance,2,world(),32,70,32));phase=2;wait=30;return;}
        if(phase==20){net.minecraft.tileentity.TileEntity local=mc.theWorld.getTileEntity(pad.xCoord,pad.yCoord,pad.zCoord);if(!(local instanceof TileLaunchFacility)||((TileLaunchFacility)local).phase!=2||!((TileLaunchFacility)local).clientShuttle){if(++timeout>120)throw new AssertionError("Client facility chunks/description not ready at "+mc.thePlayer.posX+","+mc.thePlayer.posZ);wait=10;return;}server("LC39 kit finishes server-side deployment",()->check(((TileLaunchFacility)pad).phase==2,"kit not ready "+pad.status));camera=new net.minecraft.client.entity.EntityOtherPlayerMP(mc.theWorld,mc.thePlayer.getGameProfile());camera.setPositionAndRotation(112,132,120,145,14);camera.prevPosX=camera.lastTickPosX=camera.posX;camera.prevPosY=camera.lastTickPosY=camera.posY;camera.prevPosZ=camera.lastTickPosZ=camera.posZ;camera.prevRotationYaw=camera.rotationYaw;camera.prevRotationPitch=camera.rotationPitch;mc.renderViewEntity=camera;mc.gameSettings.hideGUI=true;phase=21;wait=70;return;}
        if(phase==21){shot("shuttle-lc39-full-site");camera.setPositionAndRotation(67,110,60,140,0);camera.prevPosX=camera.lastTickPosX=camera.posX;camera.prevPosY=camera.lastTickPosY=camera.posY;camera.prevPosZ=camera.lastTickPosZ=camera.posZ;camera.prevRotationYaw=camera.rotationYaw;camera.prevRotationPitch=camera.rotationPitch;phase=22;wait=40;return;}
        if(phase==22){shot("shuttle-stack-closeup");check(GL11.glGetError()==GL11.GL_NO_ERROR,"Shuttle render GL error");pass("Full-size Shuttle and LC39 structure render without OpenGL errors");mc.renderViewEntity=mc.thePlayer;mc.gameSettings.hideGUI=false;server("New mineral blocks are visible beside the facility",()->{for(int i=0;i<6;i++)world().setBlock(28+i*2,71,48,PlanetResources.ORES[i],0,3);move(33,72,53);});phase=23;wait=50;return;}
        if(phase==23){mc.thePlayer.rotationYaw=180;mc.thePlayer.rotationPitch=10;shot("shuttle-planetary-minerals");mc.refreshResources();server("Real facility container opens at the deployed root",()->{move(pad.xCoord+.5,pad.yCoord+1,pad.zCoord+3);player().openGui(IndustrialTechnology.instance,2,world(),pad.xCoord,pad.yCoord,pad.zCoord);});phase=Boolean.getBoolean("industrialtech.shuttleGallery")?24:2;wait=50;return;}
        if(phase==24){check(mc.currentScreen instanceof GuiSpace,"Facility GUI unavailable");shot("shuttle-facility-controller");pass("Client received actual facility root, ready state and Shuttle marker");server("New assembly station opens its real server container",()->{world().setBlock(42,71,48,SpaceRegistry.machines[SpaceRegistry.ASSEMBLY],3,3);TileSpaceMachine assembly=(TileSpaceMachine)world().getTileEntity(42,71,48);assembly.owner=player().getUniqueID().toString();for(int i=0;i<11;i++)assembly.items[i]=new ItemStack(SpaceRegistry.parts[i]);assembly.energy=100000;move(42.5,72,50.5);world().markBlockForUpdate(42,71,48);});phase=26;wait=50;return;}
        if(phase==26){server("Client receives assembly block before its container opens",()->player().openGui(IndustrialTechnology.instance,2,world(),42,71,48));phase=25;wait=40;return;}
        if(phase==25){check(mc.currentScreen instanceof GuiSpace,"Assembly GUI unavailable");GuiSpace g=(GuiSpace)mc.currentScreen;check(g.state.getInteger("Target")==1,"New station not Shuttle");shot("shuttle-assembly-choice");pass("Assembly type and component checklist render with NEI enabled");finish();return;}
        if(phase==2){check(mc.currentScreen instanceof GuiSpace,"Launch planner not shown");GuiSpace g=(GuiSpace)mc.currentScreen;check(g.state.getString("Status").startsWith("Ready:"),"Launch not ready: "+g.state.getString("Status"));shot("space-launch-planner");FloatBuffer color=BufferUtils.createFloatBuffer(16);GL11.glGetFloat(GL11.GL_CURRENT_COLOR,color);check(color.get(0)>.99&&color.get(1)>.99&&color.get(2)>.99,"GUI leaked color");pass("Real launch planner displays synced tanks and restores OpenGL color");IndustrialTechnology.network.sendToServer(new SpaceCommand(g.container.windowId+50,6,0));phase=3;wait=20;return;}
        if(phase==3){server("Forged stale-window launch packet cannot spend fuel or create a vehicle",()->{check(pad.items[0]!=null&&pad.tanks[0].getFluidAmount()==SpaceConfig.moonFuel*2,"stale launch executed");});click(6);leg=0;phase=4;timeout=0;wait=10;return;}
        if(phase==4){if(mc.thePlayer.ridingEntity instanceof EntitySpaceRocket){pass("Passenger boards before server countdown / ignition");shot("space-countdown");phase=5;timeout=0;dimensionSeen=0;}else if(++timeout>80)throw new AssertionError("Boarding timeout");wait=10;return;}
        if(phase==5){int wanted=leg==0?SpaceConfig.moon:leg==2?SpaceConfig.mars:0;if(SHUTTLE)ServerWork.enqueue(()->{if(player().dimension==wanted){EntitySpaceRocket active=find();landedSignal=active.phase==EntitySpaceRocket.LANDED&&player().ridingEntity==null;}});if(mc.thePlayer.dimension==wanted)dimensionSeen+=10;if(mc.thePlayer.dimension==wanted&&dimensionSeen>=60&&mc.thePlayer.ridingEntity==null&&(!SHUTTLE||landedSignal)){server("Animated leg "+leg+" preserves inventory/XP and burns exactly one mission leg",()->{inventory();rocket=find();int expected=leg==0?SpaceConfig.moonFuel:leg==2?SpaceConfig.marsFuel:0;check(rocket.phase==EntitySpaceRocket.LANDED,"premature touchdown");check(rocket.control.tanks[0].getFluidAmount()==expected&&rocket.control.tanks[1].getFluidAmount()==expected*SpaceConfig.oxygenRatio,"wrong mission burn");landX=rocket.posX;landY=rocket.posY;landZ=rocket.posZ;});phase=6;wait=30;timeout=0;return;}if(++timeout>220)throw new AssertionError("Flight leg "+leg+" timeout; dim "+mc.thePlayer.dimension);wait=10;return;}
        if(phase==6){shot("space-landing-"+leg);if(leg==0||leg==2){camera=new net.minecraft.client.entity.EntityOtherPlayerMP(mc.theWorld,mc.thePlayer.getGameProfile());camera.setPositionAndRotation(landX+(SHUTTLE?65:18),landY+(SHUTTLE?35:5),landZ+(SHUTTLE?65:18),135,2);camera.prevPosX=camera.lastTickPosX=camera.posX;camera.prevPosY=camera.lastTickPosY=camera.posY;camera.prevPosZ=camera.lastTickPosZ=camera.posZ;camera.prevRotationYaw=camera.rotationYaw;camera.prevRotationPitch=camera.rotationPitch;mc.renderViewEntity=camera;phase=16;wait=20;return;}if(leg==1){server("Mars refuelling adds a finite 48 L kerosene / 96 L oxidizer round trip",()->{rocket=find();rocket.control.target=1;rocket.control.returnReserve=true;EntityPlayerMP p=player();int selected=p.inventory.currentItem;ItemStack old=p.inventory.mainInventory[1];ItemStack can=new ItemStack(SpaceRegistry.canister);p.inventory.mainInventory[1]=can;p.inventory.currentItem=1;ItemSpaceCanister c=(ItemSpaceCanister)SpaceRegistry.canister;for(int i=0;i<SpaceConfig.marsFuel*2/1000;i++){c.fill(can,new FluidStack(SpaceRegistry.kerosene,1000),true);rocket.interactFirst(p);check(c.getFluid(can)==null,"rocket did not consume kerosene canister");}for(int i=0;i<SpaceConfig.marsFuel*2*SpaceConfig.oxygenRatio/1000;i++){c.fill(can,new FluidStack(SpaceRegistry.lox,1000),true);rocket.interactFirst(p);check(c.getFluid(can)==null,"rocket did not consume LOX canister");}p.inventory.mainInventory[1]=old;p.inventory.currentItem=selected;move(rocket.posX+3,rocket.posY,rocket.posZ);player().openGui(IndustrialTechnology.instance,3,world(),rocket.getEntityId(),0,0);});phase=12;wait=35;return;}inventoryFinal();return;}
        if(phase==16){shot("space-vehicle-model-"+leg);mc.renderViewEntity=mc.thePlayer;mc.thePlayer.rotationYaw=0;mc.thePlayer.rotationPitch=-60;phase=17;wait=20;return;}
        if(phase==17){shot("space-sky-"+leg);mc.thePlayer.rotationPitch=0;jumpPlanet=mc.thePlayer.dimension;jumpStart=mc.thePlayer.posY;jumpMax=jumpStart;age=0;phase=7;KeyBinding.setKeyBindState(mc.gameSettings.keyBindJump.getKeyCode(),true);wait=1;return;}
        if(phase==7){age++;jumpMax=Math.max(jumpMax,mc.thePlayer.posY);if(age==5)KeyBinding.setKeyBindState(mc.gameSettings.keyBindJump.getKeyCode(),false);if(age>=100){double height=jumpMax-jumpStart;check(height>(jumpPlanet==SpaceConfig.moon?3:1.6),"planet jump height "+height);pass((jumpPlanet==SpaceConfig.moon?"Lunar":"Martian")+" client physics produces elevated jump: "+String.format(java.util.Locale.ROOT,"%.2f",height)+" blocks");if(leg==0){phase=8;server("Sealed planetary base and finite pressurizer build on the server",()->{EntityPlayerMP p=player();WorldServer w=world();int x=(int)Math.floor(landX)+12,z=(int)Math.floor(landZ),y=205;for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)for(int dy=0;dy<=4;dy++)w.setBlock(x+dx,y+dy,z+dz,dx==-2||dx==2||dz==-2||dz==2||dy==0||dy==4?SpaceRegistry.hull:Blocks.air,0,3);w.setBlock(x,y,z,SpaceRegistry.machines[7],0,3);base=(TileSpaceMachine)w.getTileEntity(x,y,z);base.owner=p.getUniqueID().toString();base.energy=1000000;base.tanks[0].fill(new FluidStack(SpaceRegistry.air,10000),true);Atmosphere.changed(w);});wait=120;return;}openRocket();phase=12;wait=35;return;}wait=1;return;}
        if(phase==8){server("Pressurized room permits helmet removal without using suit air",()->{check(base.pressure>=80&&base.sealed,"base not pressurized "+base.roomMessage+" "+base.pressure);EntityPlayerMP p=player();move(base.xCoord+.5,206,base.zCoord+.5);p.inventory.mainInventory[10]=p.inventory.armorInventory[3];p.inventory.armorInventory[3]=null;savedHealth=p.getHealth();savedAir=ItemSpaceSuit.air(p.inventory.armorInventory[2]);});phase=9;wait=90;return;}
        if(phase==9){shot("space-pressurized-base");server("Helmet-off pressure holds health and suit air; wall removal starts a real leak",()->{EntityPlayerMP p=player();check(Atmosphere.breathable(p)&&p.getHealth()==savedHealth&&ItemSpaceSuit.air(p.inventory.armorInventory[2])==savedAir,"pressure protection failed");world().setBlockToAir(base.xCoord+2,206,base.zCoord);Atmosphere.changed(world());});phase=10;wait=70;return;}
        if(phase==10){server("Breach removes breathable pressure and suit protection can be restored",()->{EntityPlayerMP p=player();check(base.pressure<80&&!Atmosphere.breathable(p),"leak not detected");p.inventory.armorInventory[3]=p.inventory.mainInventory[10];p.inventory.mainInventory[10]=null;move(landX+3,landY,landZ);rocket=find();p.openGui(IndustrialTechnology.instance,3,world(),rocket.getEntityId(),0,0);});phase=12;wait=35;return;}
        if(phase==14){finish();return;}
        if(phase==12){check(mc.currentScreen instanceof GuiSpace,"Landed vehicle planner missing");shot("space-return-planner-"+leg);landedSignal=false;click(6);leg++;phase=4;wait=10;timeout=0;return;}
    }catch(Throwable ex){failed=true;results.add("FAIL: client phase "+phase+" leg "+leg+" :: "+ex);IndustrialTechnology.log.error("Space client check",ex);shot("space-client-error");finish();}}
    private void inventoryFinal(){server("Earth return retains survival inventory, XP, armor and reusable craft",()->{inventory();check(player().dimension==0&&ItemSpaceSuit.fullTier(player())==2,"return state");rocket=find();check(rocket.control.tanks[0].getFluidAmount()==0,"free fuel");});phase=14;wait=40;}
    private void finish(){if(finished)return;finished=true;Minecraft mc=Minecraft.getMinecraft();try{results.add("Failed: "+(failed?1:0));Files.write(new File(mc.mcDataDir,"space-client-report.txt").toPath(),String.join("\n",results).getBytes(StandardCharsets.UTF_8));}catch(Exception e){IndustrialTechnology.log.error("Space client report",e);}KeyBinding.setKeyBindState(mc.gameSettings.keyBindJump.getKeyCode(),false);mc.shutdown();}
}
